import { useState, useEffect, useMemo } from "react";
import { useNavigate, useParams } from "react-router-dom";
import { Trophy, Home, RotateCcw, Crown, Medal, Loader2, BookOpen, ChevronDown, ChevronUp } from "lucide-react";
import { fetchPkRoom, fetchPkAnswers } from "@/utils/pkApi";
import { PkRoom, PkAnswer } from "@/types/pk";
import { getUserInfo } from "@/utils/userInfo";

export default function PkResult() {
  const { roomId = "" } = useParams();
  const navigate = useNavigate();
  const userInfo = getUserInfo();

  const [room, setRoom] = useState<PkRoom | null>(null);
  const [answers, setAnswers] = useState<PkAnswer[]>([]);
  const [hostTotal, setHostTotal] = useState(0);
  const [guestTotal, setGuestTotal] = useState(0);
  const [hostCorrect, setHostCorrect] = useState(0);
  const [guestCorrect, setGuestCorrect] = useState(0);
  const [winnerUuid, setWinnerUuid] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [showMyWords, setShowMyWords] = useState(false);
  const [showOpponentWords, setShowOpponentWords] = useState(false);

  useEffect(() => {
    const load = async () => {
      const r = await fetchPkRoom(roomId);
      if (r) setRoom(r);

      const ans = await fetchPkAnswers(roomId);
      setAnswers(ans);

      const hTotal = ans.reduce((s, a) => s + (a.hostScore ?? 0), 0);
      const gTotal = ans.reduce((s, a) => s + (a.guestScore ?? 0), 0);
      const hCorrect = ans.reduce(
        (n, a) => n + (a.hostAnswer === a.hostCorrectAnswer ? 1 : 0),
        0
      );
      const gCorrect = ans.reduce(
        (n, a) => n + (a.guestAnswer === a.guestCorrectAnswer ? 1 : 0),
        0
      );

      setHostTotal(hTotal);
      setGuestTotal(gTotal);
      setHostCorrect(hCorrect);
      setGuestCorrect(gCorrect);

      if (hTotal > gTotal) {
        setWinnerUuid(r?.hostUuid ?? null);
      } else if (gTotal > hTotal) {
        setWinnerUuid(r?.guestUuid ?? null);
      } else {
        setWinnerUuid(null);
      }

      setLoading(false);
    };
    load();
  }, [roomId]);

  const isHost = room ? room.hostUuid === userInfo.uuid : false;
  const myTotal = isHost ? hostTotal : guestTotal;
  const opponentTotal = isHost ? guestTotal : hostTotal;
  const myCorrect = isHost ? hostCorrect : guestCorrect;
  const opponentCorrect = isHost ? guestCorrect : hostCorrect;
  const iWon = winnerUuid === userInfo.uuid;
  const isTie = winnerUuid === null;
  const myName = isHost ? room?.hostNickname : room?.guestNickname;
  const opponentName = isHost ? room?.guestNickname : room?.hostNickname;

  const myWords = useMemo(() => {
    return answers.map((a) => {
      const word = isHost ? a.hostQuestionWord : a.guestQuestionWord;
      const correct = isHost ? a.hostCorrectAnswer : a.guestCorrectAnswer;
      const userAnswer = isHost ? a.hostAnswer : a.guestAnswer;
      return {
        word,
        correct: userAnswer === correct,
        correctAnswer: correct,
        userAnswer,
      };
    });
  }, [answers, isHost]);

  const opponentWords = useMemo(() => {
    return answers.map((a) => {
      const word = isHost ? a.guestQuestionWord : a.hostQuestionWord;
      const correct = isHost ? a.guestCorrectAnswer : a.hostCorrectAnswer;
      const userAnswer = isHost ? a.guestAnswer : a.hostAnswer;
      return {
        word,
        correct: userAnswer === correct,
        correctAnswer: correct,
        userAnswer,
      };
    });
  }, [answers, isHost]);

  if (loading) {
    return (
      <div className="h-screen bg-gradient-to-br from-slate-900 via-emerald-950 to-slate-900 flex flex-col items-center justify-center p-6">
        <div className="text-center py-16">
          <Loader2 size={40} className="mx-auto mb-4 text-emerald-400 animate-spin" />
          <p className="text-slate-300 font-medium mb-1">正在加载结果…</p>
          <p className="text-slate-500 text-sm">请稍候</p>
        </div>
      </div>
    );
  }

  return (
    <div className="h-screen bg-gradient-to-br from-slate-900 via-emerald-950 to-slate-900 flex flex-col overflow-hidden">
      <div className="flex-1 min-h-0 overflow-y-auto p-6">
        <div className="w-full max-w-sm py-6 mx-auto">
        <div className="text-center mb-8">
          {iWon ? (
            <>
              <div className="w-20 h-20 mx-auto mb-4 rounded-full bg-gradient-to-br from-amber-400 to-orange-500 flex items-center justify-center shadow-lg shadow-amber-500/30">
                <Trophy size={40} className="text-white" />
              </div>
              <p className="text-4xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-amber-300 to-orange-400 mb-2">
                🎉 你赢了！
              </p>
            </>
          ) : isTie ? (
            <>
              <div className="w-20 h-20 mx-auto mb-4 rounded-full bg-gradient-to-br from-slate-500 to-slate-600 flex items-center justify-center">
                <Medal size={40} className="text-white" />
              </div>
              <p className="text-4xl font-bold text-slate-200 mb-2">平局</p>
            </>
          ) : (
            <>
              <div className="w-20 h-20 mx-auto mb-4 rounded-full bg-gradient-to-br from-slate-600 to-slate-700 flex items-center justify-center">
                <Medal size={40} className="text-slate-300" />
              </div>
              <p className="text-4xl font-bold text-slate-300 mb-2">再接再厉</p>
            </>
          )}
          <p className="text-slate-400">
            {isTie
              ? "旗鼓相当！"
              : iWon
              ? "太棒了，继续保持！"
              : `被${opponentName || "对手"}赢了，下次加油！`}
          </p>
        </div>

        <div className="bg-slate-800/50 border border-slate-700 rounded-3xl p-6 mb-6">
          <div className="grid grid-cols-3 gap-4 items-center">
            <div className="text-center">
              <div className="w-14 h-14 mx-auto mb-2 rounded-full bg-gradient-to-br from-emerald-400 to-teal-500 flex items-center justify-center shadow-lg shadow-emerald-500/30">
                <span className="text-white font-bold text-xl">{myName?.slice(0, 1)}</span>
              </div>
              <p className="text-slate-200 font-medium text-sm truncate">{myName}</p>
              <p className="text-xs text-slate-500 mt-0.5">我</p>
            </div>

            <div className="text-center">
              <div className="flex items-center justify-center gap-2 mb-2">
                <span className="text-3xl font-bold text-emerald-300">{myTotal}</span>
                <span className="text-slate-500">:</span>
                <span className="text-3xl font-bold text-amber-300">{opponentTotal}</span>
              </div>
              <p className="text-slate-500 text-xs">
                {myCorrect} / {opponentCorrect} 对
              </p>
            </div>

            <div className="text-center">
              <div className="w-14 h-14 mx-auto mb-2 rounded-full bg-gradient-to-br from-amber-400 to-orange-500 flex items-center justify-center shadow-lg shadow-amber-500/30">
                <span className="text-white font-bold text-xl">{opponentName?.slice(0, 1) || "?"}</span>
              </div>
              <p className="text-slate-200 font-medium text-sm truncate">{opponentName || "对手"}</p>
              <p className="text-xs text-slate-500 mt-0.5">
                {winnerUuid && !iWon && !isTie ? (
                  <Crown size={12} className="inline text-amber-400" />
                ) : null}
              </p>
            </div>
          </div>
        </div>

        <div className="space-y-3 mb-6">
          <button
            onClick={() => setShowMyWords((v) => !v)}
            className="w-full p-4 bg-slate-800/50 border border-slate-700 rounded-2xl flex items-center justify-between text-left hover:bg-slate-800/70 transition-all"
          >
            <div className="flex items-center gap-3">
              <BookOpen size={18} className="text-emerald-400" />
              <div>
                <p className="text-slate-200 font-medium">我的答题单词</p>
                <p className="text-xs text-slate-500">{myCorrect} 对 / {myWords.length} 题</p>
              </div>
            </div>
            {showMyWords ? <ChevronUp size={18} className="text-slate-400" /> : <ChevronDown size={18} className="text-slate-400" />}
          </button>
          {showMyWords && (
            <div className="bg-slate-900/50 border border-slate-700/50 rounded-2xl p-4 max-h-72 overflow-y-auto space-y-2">
              {myWords.map((w, i) => (
                <div key={i} className="py-2 px-3 rounded-lg bg-slate-800/50">
                  <div className="flex items-center justify-between">
                    <span className="text-slate-200 font-medium">{w.word}</span>
                    <span className={`text-xs font-medium px-2 py-0.5 rounded-full ${
                      w.correct ? "bg-emerald-500/20 text-emerald-300" : "bg-rose-500/20 text-rose-300"
                    }`}>
                      {w.correct ? "✓ 正确" : `✗ 错误`}
                    </span>
                  </div>
                  {!w.correct && (
                    <div className="mt-1.5 text-xs space-y-0.5">
                      <p className="text-slate-400">
                      你的答案：<span className="text-rose-300">{w.userAnswer || "未答"}</span>
                    </p>
                      <p className="text-slate-400">
                      正确答案：<span className="text-emerald-300">{w.correctAnswer}</span>
                    </p>
                    </div>
                  )}
                </div>
              ))}
            </div>
          )}

          <button
            onClick={() => setShowOpponentWords((v) => !v)}
            className="w-full p-4 bg-slate-800/50 border border-slate-700 rounded-2xl flex items-center justify-between text-left hover:bg-slate-800/70 transition-all"
          >
            <div className="flex items-center gap-3">
              <BookOpen size={18} className="text-amber-400" />
              <div>
                <p className="text-slate-200 font-medium">{opponentName || "对手"}的答题单词</p>
                <p className="text-xs text-slate-500">{opponentCorrect} 对 / {opponentWords.length} 题</p>
              </div>
            </div>
            {showOpponentWords ? <ChevronUp size={18} className="text-slate-400" /> : <ChevronDown size={18} className="text-slate-400" />}
          </button>
          {showOpponentWords && (
            <div className="bg-slate-900/50 border border-slate-700/50 rounded-2xl p-4 max-h-72 overflow-y-auto space-y-2">
              {opponentWords.map((w, i) => (
                <div key={i} className="py-2 px-3 rounded-lg bg-slate-800/50">
                  <div className="flex items-center justify-between">
                    <span className="text-slate-200 font-medium">{w.word}</span>
                    <span className={`text-xs font-medium px-2 py-0.5 rounded-full ${
                      w.correct ? "bg-emerald-500/20 text-emerald-300" : "bg-rose-500/20 text-rose-300"
                    }`}>
                      {w.correct ? "✓ 正确" : `✗ 错误`}
                    </span>
                  </div>
                  {!w.correct && (
                    <div className="mt-1.5 text-xs space-y-0.5">
                      <p className="text-slate-400">
                        对手答案：<span className="text-rose-300">{w.userAnswer || "未答"}</span>
                      </p>
                      <p className="text-slate-400">
                        正确答案：<span className="text-emerald-300">{w.correctAnswer}</span>
                      </p>
                    </div>
                  )}
                </div>
              ))}
            </div>
          )}
        </div>

        <div className="flex flex-col gap-3">
          <button
            onClick={() => navigate("/pk")}
            className="w-full py-4 bg-gradient-to-r from-emerald-500 to-teal-500 text-white font-bold text-lg rounded-2xl shadow-lg shadow-emerald-500/30 hover:scale-105 active:scale-95 transition-all flex items-center justify-center gap-2"
          >
            <RotateCcw size={20} />
            再来一局
          </button>

          <button
            onClick={() => navigate("/")}
            className="w-full py-4 bg-slate-700/50 text-slate-200 font-bold text-lg rounded-2xl hover:bg-slate-700 active:scale-95 transition-all flex items-center justify-center gap-2"
          >
            <Home size={20} />
            返回首页
          </button>
        </div>
        </div>
      </div>
    </div>
  );
}
