import { useNavigate } from "react-router-dom";
import { useEffect, useRef, useState } from "react";
import { Sprout, ArrowLeft, Loader2 } from "lucide-react";
import { useGameStore } from "@/store/useGameStore";
import { useFarmUI } from "@/hooks/useFarmUI";
import { useFarmStore } from "@/store/useFarmStore";
import {
  TabBar, QuizButton, DebugButtons, TabContent,
} from "@/components/FarmContent";
import QuizModal from "@/components/QuizModal";
import { showToast } from "@/utils/toast";

export default function FarmPage() {
  const navigate = useNavigate();
  const ui = useFarmUI(true);
  const sunlight = useGameStore((s) => s.sunlight);
  const syncStolenFromCloud = useFarmStore((s) => s.syncStolenFromCloud);

  const [syncReady, setSyncReady] = useState(false);
  const showToastRef = useRef(showToast);
  showToastRef.current = showToast;

  useEffect(() => {
    let cancelled = false;

    (async () => {
      try {
        const count = await syncStolenFromCloud();
        if (cancelled) return;
        if (count > 0) {
          showToastRef.current(`农场数据已同步（${count} 条更新）`, "success");
        }
      } catch (e) {
        console.error("同步农场数据失败:", e);
        showToastRef.current("同步农场数据失败，请稍后再试", "error");
      } finally {
        if (!cancelled) setSyncReady(true);
      }
    })();

    return () => { cancelled = true; };
  }, [syncStolenFromCloud]);

  return (
    <div className="h-screen bg-gradient-to-br from-slate-900 via-emerald-950 to-slate-900">
      <div className="max-w-md mx-auto px-4 py-6 flex flex-col h-screen">
        <div className="shrink-0">
        <div className="flex items-center justify-between mb-6">
          <button
            onClick={() => navigate("/")}
            className="p-2 rounded-full hover:bg-slate-700/50 text-slate-400 hover:text-slate-200 transition-all"
          >
            <ArrowLeft size={22} />
          </button>

          <div className="flex items-center gap-2">
            <div className="w-10 h-10 rounded-full bg-gradient-to-br from-emerald-400 to-teal-500 flex items-center justify-center shadow-lg shadow-emerald-500/50">
              <Sprout className="text-white" size={20} />
            </div>
            <h1 className="text-xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-emerald-400 via-teal-400 to-cyan-400">
              我的农场
            </h1>
          </div>

          <div className="flex items-center gap-1">
            <span className="text-yellow-400 text-lg">☀️</span>
            <span className="text-yellow-300 font-bold">{sunlight}</span>
          </div>
        </div>

        <QuizButton ui={ui} />
        {import.meta.env.DEV && <DebugButtons ui={ui} />}
        <TabBar ui={ui} />
        </div>

        <div className="flex-1 overflow-y-auto min-h-0">
          {!syncReady ? (
            <div className="h-full flex items-center justify-center">
              <div className="text-center">
                <Loader2 size={32} className="mx-auto mb-2 text-emerald-400 animate-spin" />
                <p className="text-emerald-300 text-xs">正在同步农场数据…</p>
              </div>
            </div>
          ) : (
            <TabContent ui={ui} showDeliveryEntry />
          )}
        </div>
      </div>
      <QuizModal open={ui.showQuiz} onClose={() => ui.setShowQuiz(false)} mode="farm" />
    </div>
  );
}
