import { useEffect, useRef, useState } from "react";
import { subscribeToast, ToastMessage } from "@/utils/toast";

const TOAST_DURATION_MS = 2500;

export default function ToastView() {
  const [message, setMessage] = useState<ToastMessage | null>(null);
  const timerRef = useRef<number | null>(null);

  useEffect(() => {
    const dispose = subscribeToast((msg) => {
      setMessage(msg);
      if (timerRef.current !== null) {
        clearTimeout(timerRef.current);
      }
      timerRef.current = window.setTimeout(() => {
        setMessage(null);
        timerRef.current = null;
      }, TOAST_DURATION_MS);
    });
    return () => {
      dispose();
      if (timerRef.current !== null) {
        clearTimeout(timerRef.current);
        timerRef.current = null;
      }
    };
  }, []);

  if (!message) return null;

  return (
    <div
      className={`fixed top-4 left-1/2 -translate-x-1/2 z-[100] text-center py-2 px-4 rounded-xl text-sm shadow-lg pointer-events-none animate-[fadeIn_0.2s_ease-out] max-w-[90vw] ${
        message.type === "success"
          ? "bg-emerald-600/90 text-white border border-emerald-400/40"
          : "bg-rose-600/90 text-white border border-rose-400/40"
      }`}
    >
      {message.text}
    </div>
  );
}