import { SeedType, SEED_CONFIGS, ShapeCell } from "@/types/game";
import {
  DeliveryOrder,
  OrderCondition,
  VEHICLE_TYPES,
} from "@/types/delivery";

const ALL_SEED_TYPES: SeedType[] = ["carrot", "strawberry", "cucumber", "tomato", "cabbage", "corn", "sunflower", "watermelon", "kiwi", "eggplant", "grapes"];

function cellCount(seed: SeedType): number {
  return SEED_CONFIGS[seed].shapes[0].length;
}

function weightOf(seed: SeedType): number {
  return SEED_CONFIGS[seed].weight;
}

function getCells(seed: SeedType, rot: number): ShapeCell[] {
  const r = ((rot % 4) + 4) % 4;
  return SEED_CONFIGS[seed].shapes[r];
}

// 生成随机障碍物
function generateObstacles(gridRows: number, gridCols: number): { row: number; col: number }[] {
  const count = 3 + Math.floor(Math.random() * 3); // 3-5 个
  const occupied = new Set<string>();
  const result: { row: number; col: number }[] = [];
  let attempts = 0;
  while (result.length < count && attempts < 100) {
    const r = Math.floor(Math.random() * gridRows);
    const c = Math.floor(Math.random() * gridCols);
    const key = `${r},${c}`;
    if (!occupied.has(key)) {
      occupied.add(key);
      result.push({ row: r, col: c });
    }
    attempts++;
  }
  return result;
}

// 判断一组形状物品是否能放入网格（带障碍物）
// 使用回溯法，对小网格足够快；加超时保护避免卡死
function canPack(
  items: { seed: SeedType }[],
  gridRows: number,
  gridCols: number,
  obstacles: { row: number; col: number }[],
  timeLimitMs: number = 80
): boolean {
  const obstacleSet = new Set(obstacles.map((o) => `${o.row},${o.col}`));
  const grid: boolean[][] = Array.from({ length: gridRows }, () =>
    Array.from({ length: gridCols }, () => false)
  );
  const startTime = Date.now();
  let timedOut = false;

  function placeAt(row: number, col: number, cells: ShapeCell[]): boolean {
    for (const cell of cells) {
      const r = row + cell.dr;
      const c = col + cell.dc;
      if (r < 0 || r >= gridRows || c < 0 || c >= gridCols) return false;
      if (obstacleSet.has(`${r},${c}`)) return false;
      if (grid[r][c]) return false;
    }
    return true;
  }

  function commit(row: number, col: number, cells: ShapeCell[], val: boolean) {
    for (const cell of cells) {
      grid[row + cell.dr][col + cell.dc] = val;
    }
  }

  function backtrack(idx: number): boolean {
    if (timedOut) return false;
    if (Date.now() - startTime > timeLimitMs) {
      timedOut = true;
      return false;
    }
    if (idx >= items.length) return true;
    const seed = items[idx].seed;
    for (let rot = 0; rot < 4; rot++) {
      const cells = getCells(seed, rot);
      for (let r = 0; r < gridRows; r++) {
        for (let c = 0; c < gridCols; c++) {
          if (placeAt(r, c, cells)) {
            commit(r, c, cells, true);
            if (backtrack(idx + 1)) return true;
            commit(r, c, cells, false);
          }
        }
      }
    }
    return false;
  }

  return backtrack(0);
}

// 生成有难度但有解的订单
export function generateOrder(): DeliveryOrder | null {
  const vehicle = VEHICLE_TYPES[0];
  const { gridRows, gridCols, capacity } = vehicle;
  const totalCells = gridRows * gridCols;

  // 尝试多次，找到可行的
  for (let attempt = 0; attempt < 30; attempt++) {
    const obstacles = generateObstacles(gridRows, gridCols);
    const availCells = totalCells - obstacles.length;

    // 找利用率在 75%-95% 之间的组合
    const combos: { seeds: SeedType[]; totalWeight: number; variety: number; cellCount: number }[] = [];

    function addComboIfValid(seeds: SeedType[]) {
      const unique = new Set(seeds);
      const tc = seeds.reduce((s, x) => s + cellCount(x), 0);
      const tw = seeds.reduce((s, x) => s + weightOf(x), 0);
      if (
        tc >= availCells * 0.75 && tc <= availCells * 0.95 &&
        tw <= capacity &&
        unique.size >= 2
      ) {
        combos.push({ seeds: [...seeds], totalWeight: tw, variety: unique.size, cellCount: tc });
      }
    }

      // 2 种水果（各 1 个）
      for (let i = 0; i < ALL_SEED_TYPES.length; i++) {
        for (let j = i + 1; j < ALL_SEED_TYPES.length; j++) {
          addComboIfValid([ALL_SEED_TYPES[i], ALL_SEED_TYPES[j]]);
        }
      }

      // 2 种水果（2+1 或 1+2）
      for (let i = 0; i < ALL_SEED_TYPES.length; i++) {
        for (let j = i + 1; j < ALL_SEED_TYPES.length; j++) {
          addComboIfValid([ALL_SEED_TYPES[i], ALL_SEED_TYPES[i], ALL_SEED_TYPES[j]]);
          addComboIfValid([ALL_SEED_TYPES[i], ALL_SEED_TYPES[j], ALL_SEED_TYPES[j]]);
        }
      }

      // 2 种水果（2+2）
      for (let i = 0; i < ALL_SEED_TYPES.length; i++) {
        for (let j = i + 1; j < ALL_SEED_TYPES.length; j++) {
          addComboIfValid([
            ALL_SEED_TYPES[i], ALL_SEED_TYPES[i],
            ALL_SEED_TYPES[j], ALL_SEED_TYPES[j],
          ]);
        }
      }

      // 3 种水果（各 1 个）
      for (let i = 0; i < ALL_SEED_TYPES.length; i++) {
        for (let j = i + 1; j < ALL_SEED_TYPES.length; j++) {
          for (let k = j + 1; k < ALL_SEED_TYPES.length; k++) {
            addComboIfValid([ALL_SEED_TYPES[i], ALL_SEED_TYPES[j], ALL_SEED_TYPES[k]]);
          }
        }
      }

      // 3 种水果（2+1+1）
      for (let i = 0; i < ALL_SEED_TYPES.length; i++) {
        for (let j = i + 1; j < ALL_SEED_TYPES.length; j++) {
          for (let k = j + 1; k < ALL_SEED_TYPES.length; k++) {
            addComboIfValid([ALL_SEED_TYPES[i], ALL_SEED_TYPES[i], ALL_SEED_TYPES[j], ALL_SEED_TYPES[k]]);
            addComboIfValid([ALL_SEED_TYPES[i], ALL_SEED_TYPES[j], ALL_SEED_TYPES[j], ALL_SEED_TYPES[k]]);
            addComboIfValid([ALL_SEED_TYPES[i], ALL_SEED_TYPES[j], ALL_SEED_TYPES[k], ALL_SEED_TYPES[k]]);
          }
        }
      }

    // 按形状可放置性过滤（每个最多试 80ms）
    const feasible = combos.filter((c) =>
      canPack(c.seeds.map((s) => ({ seed: s })), gridRows, gridCols, obstacles, 80)
    );

    if (feasible.length > 0) {
      // 排序：优先多样化（3种 > 2种），多样化内按格子利用率从高到低
      feasible.sort((a, b) => {
        if (b.variety !== a.variety) return b.variety - a.variety;
        return b.cellCount - a.cellCount;
      });

      // 从前 5 个里随机选
      const topCandidates = feasible.slice(0, 5);
      const combo = topCandidates[Math.floor(Math.random() * topCandidates.length)];

      // 统计每种水果数量
      const counts: Partial<Record<SeedType, number>> = {};
      for (const s of combo.seeds) counts[s] = (counts[s] || 0) + 1;

      const usedInCombo = new Set(combo.seeds);
      const notUsed = ALL_SEED_TYPES.filter((s) => !usedInCombo.has(s));

      // 构建条件（全部使用 exact，必须正好 N 个）
      const conditions: OrderCondition[] = [];
      const countEntries = Object.entries(counts) as [SeedType, number][];

      for (let i = 0; i < countEntries.length; i++) {
        const [seed, count] = countEntries[i];
        conditions.push({ type: "exact", seedType: seed, count });
      }

      // 禁 2-3 种水果
      if (notUsed.length > 0) {
        const forbidCount = Math.min(notUsed.length, 2 + Math.floor(Math.random() * 2)); // 2-3 种
        const shuffled = [...notUsed].sort(() => Math.random() - 0.5);
        const forbidden = shuffled.slice(0, forbidCount);
        conditions.push({ type: "forbidden", seedTypes: forbidden });
      }

      // 目标重量设为组合总重量 ± 一定范围，让玩家需要通过重量判断
      const weightTolerance = Math.max(2, Math.floor(combo.totalWeight * 0.3));
      const targetWeight = Math.max(3, combo.totalWeight - weightTolerance);
      const maxWeight = combo.totalWeight + weightTolerance;

      // 奖励（以答题为主要积分来源，配送作为辅助）：5-12 阳光随机
      const baseReward = 5 + Math.floor(Math.random() * 8);

      const id = "order_" + Date.now() + "_" + Math.random().toString(36).slice(2, 8);

      return {
        id,
        conditions,
        targetWeight,
        maxWeight,
        vehicleId: vehicle.id,
        obstacles,
        baseReward,
        createdAt: Date.now(),
        status: "available",
        loadedItems: {},
      };
    }
  }

  return null;
}

// 生成多个订单
export function generateOrders(count: number = 3): DeliveryOrder[] {
  const orders: DeliveryOrder[] = [];
  const used = new Set<string>();

  for (let i = 0; i < count * 10 && orders.length < count; i++) {
    const order = generateOrder();
    if (!order) break;
    const key = order.conditions
      .map((c) => JSON.stringify(c))
      .sort()
      .join("|");
    if (!used.has(key)) {
      used.add(key);
      orders.push(order);
    }
  }

  return orders;
}
