import { useState, useEffect, useMemo } from "react";
import { BookOpen, Plus, Edit2, Trash2, X, Check, Search, AlertCircle, Upload, Copy, Lightbulb, Download, History } from "lucide-react";
import { useWordStore } from "@/store/useWordStore";
import { Word, ImportRecord } from "@/types/game";
import { copyToClipboard } from "@/lib/utils";

interface WordListModalProps {
  open: boolean;
  onClose: () => void;
}

type TabType = "words" | "wrong";

export default function WordListModal({ open, onClose }: WordListModalProps) {
  const words = useWordStore((s) => s.words);
  const wrongWords = useWordStore((s) => s.wrongWords);
  const importHistory = useWordStore((s) => s.importHistory);
  const loadWords = useWordStore((s) => s.loadWords);
  const loadImportHistory = useWordStore((s) => s.loadImportHistory);
  const clearImportHistory = useWordStore((s) => s.clearImportHistory);
  const addWord = useWordStore((s) => s.addWord);
  const updateWord = useWordStore((s) => s.updateWord);
  const deleteWord = useWordStore((s) => s.deleteWord);
  const removeWrongWord = useWordStore((s) => s.removeWrongWord);
  const clearWrongWords = useWordStore((s) => s.clearWrongWords);
  const importWords = useWordStore((s) => s.importWords);
  const exportWords = useWordStore((s) => s.exportWords);

  const [activeTab, setActiveTab] = useState<TabType>("words");
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editSpelling, setEditSpelling] = useState("");
  const [editMeaning, setEditMeaning] = useState("");
  const [showAdd, setShowAdd] = useState(false);
  const [newSpelling, setNewSpelling] = useState("");
  const [newMeaning, setNewMeaning] = useState("");
  const [searchQuery, setSearchQuery] = useState("");
  const [showImport, setShowImport] = useState(false);
  const [showHistory, setShowHistory] = useState(false);
  const [importText, setImportText] = useState("");
  const [importMsg, setImportMsg] = useState<{ text: string; type: "success" | "error" } | null>(null);
  const [exportMsg, setExportMsg] = useState<string | null>(null);
  const [copyFailed, setCopyFailed] = useState(false);
  const [historyCopiedId, setHistoryCopiedId] = useState<string | null>(null);

  useEffect(() => {
    if (open) {
      loadWords();
      loadImportHistory();
      setSearchQuery("");
      setShowAdd(false);
      setShowHistory(false);
      setEditingId(null);
      setCopyFailed(false);
      setExportMsg(null);
    }
  }, [open, loadWords, loadImportHistory]);

  const displayList = activeTab === "words" ? words : wrongWords;

  const filteredWords = useMemo(() => {
    if (!searchQuery.trim()) return displayList;
    const q = searchQuery.toLowerCase().trim();
    return displayList.filter(
      (w) => w.spelling.toLowerCase().includes(q) || w.meaning.toLowerCase().includes(q)
    );
  }, [displayList, searchQuery]);

  const startEdit = (word: Word) => {
    setEditingId(word.id);
    setEditSpelling(word.spelling);
    setEditMeaning(word.meaning);
  };

  const saveEdit = () => {
    if (editingId && editSpelling.trim() && editMeaning.trim()) {
      updateWord(editingId, editSpelling, editMeaning);
    }
    setEditingId(null);
  };

  const handleAdd = () => {
    if (newSpelling.trim() && newMeaning.trim()) {
      addWord(newSpelling, newMeaning);
      setNewSpelling("");
      setNewMeaning("");
      setShowAdd(false);
    }
  };

  const handleTabChange = (tab: TabType) => {
    setActiveTab(tab);
    setSearchQuery("");
    setEditingId(null);
    setShowAdd(false);
    setShowImport(false);
    setShowHistory(false);
    setImportMsg(null);
    setCopyFailed(false);
    setExportMsg(null);
  };

  const handleExport = async () => {
    const data = exportWords();
    if (data.length === 0) {
      setExportMsg("暂无单词可导出");
      setTimeout(() => setExportMsg(null), 2000);
      return;
    }
    const jsonStr = JSON.stringify(data, null, 2);
    const ok = await copyToClipboard(jsonStr);
    if (ok) {
      setExportMsg(`已导出 ${data.length} 个单词到剪贴板`);
    } else {
      setExportMsg("导出失败，请重试");
    }
    setTimeout(() => setExportMsg(null), 2000);
  };

  const handleHistoryCopy = async (record: ImportRecord) => {
    const jsonStr = JSON.stringify(record.words, null, 2);
    const ok = await copyToClipboard(jsonStr);
    if (ok) {
      setHistoryCopiedId(record.id);
      setTimeout(() => setHistoryCopiedId(null), 2000);
    }
  };

  const formatTime = (ts: number) => {
    const d = new Date(ts);
    return `${d.getMonth() + 1}/${d.getDate()} ${d.getHours().toString().padStart(2, "0")}:${d.getMinutes().toString().padStart(2, "0")}`;
  };

  const IMPORT_PROMPT = `请将这些英语单词，以 JSON 格式输出。

要求：
1. 必须是数组格式
2. 每个元素包含 word 和 desc 两个字段
3. word 是单词拼写，desc 是中文解释
4. 只输出 JSON，不要包含任何其他文字、解释或 markdown 格式

示例格式：
[{"word":"apple","desc":"苹果"},{"word":"book","desc":"书本"}]

请直接输出 JSON 内容：`;

  const copyPrompt = () => {
    copyToClipboard(IMPORT_PROMPT).then((ok) => {
      if (ok) {
        setImportMsg({ text: "提示词已复制到剪贴板", type: "success" });
        setCopyFailed(false);
        setTimeout(() => setImportMsg(null), 2000);
      } else {
        setImportMsg({ text: "复制失败，请手动复制", type: "error" });
        setCopyFailed(true);
        setTimeout(() => setImportMsg(null), 2000);
      }
    });
  };

  const handleImport = () => {
    if (!importText.trim()) {
      setImportMsg({ text: "请输入 JSON 内容", type: "error" });
      return;
    }
    const result = importWords(importText);
    setImportMsg({ text: result.message, type: result.success ? "success" : "error" });
    if (result.success) {
      setImportText("");
      setTimeout(() => {
        setShowImport(false);
        setImportMsg(null);
      }, 1500);
    }
  };

  if (!open) return null;

  const isWrongTab = activeTab === "wrong";

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-black/80 backdrop-blur-md" onClick={onClose} />
      <div
        className={`relative bg-gradient-to-br from-slate-900 via-slate-800 to-slate-900 border rounded-3xl p-6 sm:p-8 max-w-md w-full shadow-2xl max-h-[90vh] flex flex-col ${
          isWrongTab ? "border-rose-500/30" : "border-emerald-500/30"
        }`}
      >
        <div className="absolute -top-6 left-1/2 -translate-x-1/2">
          <div
            className={`w-12 h-12 rounded-full flex items-center justify-center shadow-lg ${
              isWrongTab
                ? "bg-gradient-to-br from-rose-400 to-red-500 shadow-rose-500/50"
                : "bg-gradient-to-br from-emerald-400 to-teal-500 shadow-emerald-500/50"
            }`}
          >
            {isWrongTab ? (
              <AlertCircle className="text-white" size={24} />
            ) : (
              <BookOpen className="text-white" size={24} />
            )}
          </div>
        </div>

        <h2
          className={`text-2xl font-bold text-transparent bg-clip-text mb-2 mt-4 text-center ${
            isWrongTab
              ? "bg-gradient-to-r from-rose-400 via-red-400 to-orange-400"
              : "bg-gradient-to-r from-emerald-400 via-teal-400 to-cyan-400"
          }`}
        >
          {isWrongTab ? "错题本" : "我的单词本"}
        </h2>

        <div className="flex gap-2 mb-3 bg-slate-800/50 rounded-xl p-1">
          <button
            onClick={() => handleTabChange("words")}
            className={`flex-1 py-2 rounded-lg text-sm font-medium transition-all ${
              activeTab === "words"
                ? "bg-emerald-500/30 text-emerald-300"
                : "text-slate-400 hover:text-slate-300"
            }`}
          >
            全部单词 ({words.length})
          </button>
          <button
            onClick={() => handleTabChange("wrong")}
            className={`flex-1 py-2 rounded-lg text-sm font-medium transition-all ${
              activeTab === "wrong"
                ? "bg-rose-500/30 text-rose-300"
                : "text-slate-400 hover:text-slate-300"
            }`}
          >
            错题本 ({wrongWords.length})
          </button>
        </div>

        {!isWrongTab && (
          <p className="text-center text-slate-400 text-sm mb-3">
            已收录{" "}
            <span className={`font-bold ${words.length >= 10 ? "text-emerald-400" : "text-amber-400"}`}>
              {words.length}
            </span>{" "}
            / 10 个单词
            {words.length < 10 && <span className="text-amber-400">（满10个可开启赚积分）</span>}
          </p>
        )}

        {isWrongTab && wrongWords.length > 0 && (
          <p className="text-center text-slate-400 text-sm mb-3">
            共 <span className="text-rose-400 font-bold">{wrongWords.length}</span> 个需要复习的错题
          </p>
        )}

        {displayList.length > 0 && (
          <div className="relative mb-3">
            <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-500" />
            <input
              type="text"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              placeholder="搜索单词或解释..."
              className="w-full bg-slate-900/50 text-slate-200 pl-9 pr-3 py-2 rounded-xl border border-slate-600/50 focus:border-emerald-500 focus:outline-none text-sm placeholder:text-slate-500"
            />
            {searchQuery && (
              <button
                onClick={() => setSearchQuery("")}
                className="absolute right-2 top-1/2 -translate-y-1/2 p-1 text-slate-500 hover:text-slate-300"
              >
                <X size={14} />
              </button>
            )}
          </div>
        )}

        <div className="flex-1 overflow-y-auto mb-4 pr-1 -mr-1">
          <div className="flex flex-col gap-2">
            {!isWrongTab && showImport && (
              <div className="bg-violet-900/30 rounded-2xl p-4 border border-violet-500/30">
                <div className="flex items-center justify-between mb-3">
                  <p className="text-violet-300 font-semibold text-sm flex items-center gap-2">
                    <Upload size={16} /> 批量导入单词
                  </p>
                  <button
                    onClick={() => {
                      setShowImport(false);
                      setImportMsg(null);
                      setImportText("");
                    }}
                    className="p-1 text-slate-500 hover:text-slate-300"
                  >
                    <X size={16} />
                  </button>
                </div>

                <div className="bg-slate-900/60 rounded-xl p-3 mb-3 border border-slate-700/50">
                  <div className="flex items-start justify-between gap-2">
                    <div className="flex items-start gap-2 flex-1">
                      <Lightbulb size={14} className="text-amber-400 mt-0.5 shrink-0" />
                      <p className="text-slate-400 text-xs leading-relaxed">
                        复制下方提示词发送给 AI（如豆包、ChatGPT 等），将返回的 JSON 粘贴到输入框即可批量导入。
                      </p>
                    </div>
                    <button
                      onClick={copyPrompt}
                      className="shrink-0 px-3 py-1.5 bg-violet-500/30 hover:bg-violet-500/50 text-violet-300 rounded-lg text-xs font-medium transition-all flex items-center gap-1"
                    >
                      <Copy size={12} /> 复制
                    </button>
                  </div>
                </div>

                {copyFailed && (
                  <div className="mb-3">
                    <p className="text-xs text-slate-400 mb-2">复制失败，请手动选择下方文本复制：</p>
                    <textarea
                      readOnly
                      value={IMPORT_PROMPT}
                      onClick={(e) => e.currentTarget.select()}
                      className="w-full bg-slate-900/50 text-slate-200 px-3 py-2 rounded-xl border border-slate-600/50 text-xs font-mono h-32 resize-none"
                    />
                  </div>
                )}

                <textarea
                  value={importText}
                  onChange={(e) => setImportText(e.target.value)}
                  placeholder='粘贴 JSON 内容，例如：[{"word":"apple","desc":"苹果"}]'
                  className="w-full bg-slate-900/50 text-slate-200 px-3 py-2 rounded-xl border border-slate-600/50 focus:border-violet-500 focus:outline-none text-sm font-mono resize-none h-24 placeholder:text-slate-500"
                />

                {importMsg && (
                  <p
                    className={`text-xs mt-2 ${
                      importMsg.type === "success" ? "text-emerald-400" : "text-rose-400"
                    }`}
                  >
                    {importMsg.text}
                  </p>
                )}

                <button
                  onClick={handleImport}
                  className="w-full mt-3 py-2 bg-gradient-to-r from-violet-500 to-purple-500 hover:from-violet-400 hover:to-purple-400 text-white font-medium rounded-xl text-sm transition-all shadow-lg shadow-violet-500/20"
                >
                  确认导入
                </button>

                {/* 导入历史 */}
                {importHistory.length > 0 && (
                  <div className="mt-4 pt-3 border-t border-slate-700/50">
                    <button
                      onClick={() => setShowHistory(!showHistory)}
                      className="flex items-center justify-between w-full text-slate-400 hover:text-slate-300 transition-all"
                    >
                      <span className="text-xs font-medium flex items-center gap-1.5">
                        <History size={14} /> 导入历史（{importHistory.length}）
                      </span>
                      <span className="text-xs">{showHistory ? "收起" : "展开"}</span>
                    </button>

                    {showHistory && (
                      <div className="mt-2 flex flex-col gap-1.5">
                        {[...importHistory].reverse().map((record) => (
                          <div
                            key={record.id}
                            className="flex items-center justify-between bg-slate-900/50 rounded-lg px-3 py-2 border border-slate-700/30"
                          >
                            <div className="flex-1 min-w-0">
                              <p className="text-slate-300 text-xs font-medium">
                                {formatTime(record.timestamp)}
                              </p>
                              <p className="text-slate-500 text-[10px]">
                                {record.count} 个单词
                              </p>
                            </div>
                            <button
                              onClick={() => handleHistoryCopy(record)}
                              className="shrink-0 px-2.5 py-1.5 rounded-lg text-xs font-medium transition-all flex items-center gap-1"
                            >
                              {historyCopiedId === record.id ? (
                                <span className="text-emerald-400 flex items-center gap-1">
                                  <Check size={12} /> 已复制
                                </span>
                              ) : (
                                <span className="text-violet-300 flex items-center gap-1">
                                  <Copy size={12} /> 复制
                                </span>
                              )}
                            </button>
                          </div>
                        ))}
                        {importHistory.length > 0 && (
                          <button
                            onClick={() => {
                              if (confirm("确定清空所有导入历史吗？")) {
                                clearImportHistory();
                              }
                            }}
                            className="text-center text-slate-500 hover:text-rose-400 text-[10px] py-1 transition-all"
                          >
                            清空历史
                          </button>
                        )}
                      </div>
                    )}
                  </div>
                )}
              </div>
            )}

            {!isWrongTab && showAdd && (
              <div className="bg-emerald-900/30 rounded-2xl p-4 border border-emerald-500/30">
                <div className="flex flex-col gap-2">
                  <input
                    type="text"
                    placeholder="单词拼写"
                    value={newSpelling}
                    onChange={(e) => setNewSpelling(e.target.value)}
                    className="w-full bg-slate-900/50 text-slate-200 px-3 py-2 rounded-xl border border-slate-600/50 focus:border-emerald-500 focus:outline-none text-sm"
                  />
                  <input
                    type="text"
                    placeholder="中文解释"
                    value={newMeaning}
                    onChange={(e) => setNewMeaning(e.target.value)}
                    className="w-full bg-slate-900/50 text-slate-200 px-3 py-2 rounded-xl border border-slate-600/50 focus:border-emerald-500 focus:outline-none text-sm"
                  />
                  <div className="flex gap-2">
                    <button
                      onClick={handleAdd}
                      className="flex-1 py-2 bg-emerald-500/30 hover:bg-emerald-500/50 text-emerald-300 rounded-xl text-sm font-medium transition-all flex items-center justify-center gap-1"
                    >
                      <Check size={16} /> 添加
                    </button>
                    <button
                      onClick={() => {
                        setShowAdd(false);
                        setNewSpelling("");
                        setNewMeaning("");
                      }}
                      className="py-2 px-4 bg-slate-700/50 hover:bg-slate-600/50 text-slate-300 rounded-xl text-sm font-medium transition-all"
                    >
                      取消
                    </button>
                  </div>
                </div>
              </div>
            )}

            {exportMsg && (
              <div className="bg-sky-500/10 border border-sky-500/30 rounded-xl px-4 py-2.5 text-sky-300 text-sm text-center">
                {exportMsg}
              </div>
            )}

            {filteredWords.length === 0 && !showAdd && (
              <div className="text-center text-slate-500 py-8">
                {searchQuery
                  ? "没有找到匹配的单词"
                  : isWrongTab
                  ? "暂无错题，继续加油！"
                  : "暂无单词，点击下方添加"}
              </div>
            )}

            {filteredWords.map((word) => (
              <div
                key={word.id}
                className={`bg-slate-800/50 rounded-2xl px-4 py-3 border ${
                  isWrongTab ? "border-rose-500/20" : "border-slate-700/50"
                }`}
              >
                {editingId === word.id ? (
                  <div className="flex flex-col gap-2">
                    <input
                      type="text"
                      value={editSpelling}
                      onChange={(e) => setEditSpelling(e.target.value)}
                      className="w-full bg-slate-900/50 text-slate-200 px-3 py-2 rounded-xl border border-slate-600/50 focus:border-emerald-500 focus:outline-none text-sm"
                    />
                    <input
                      type="text"
                      value={editMeaning}
                      onChange={(e) => setEditMeaning(e.target.value)}
                      className="w-full bg-slate-900/50 text-slate-200 px-3 py-2 rounded-xl border border-slate-600/50 focus:border-emerald-500 focus:outline-none text-sm"
                    />
                    <div className="flex gap-2">
                      <button
                        onClick={saveEdit}
                        className="flex-1 py-1.5 bg-emerald-500/30 hover:bg-emerald-500/50 text-emerald-300 rounded-xl text-sm font-medium transition-all flex items-center justify-center gap-1"
                      >
                        <Check size={14} /> 保存
                      </button>
                      <button
                        onClick={() => setEditingId(null)}
                        className="py-1.5 px-4 bg-slate-700/50 hover:bg-slate-600/50 text-slate-300 rounded-xl text-sm font-medium transition-all"
                      >
                        取消
                      </button>
                    </div>
                  </div>
                ) : (
                  <div className="flex items-center justify-between gap-3">
                    <div className="flex-1 min-w-0">
                      <p className={`font-semibold truncate ${isWrongTab ? "text-rose-300" : "text-emerald-300"}`}>
                        {word.spelling}
                      </p>
                      <p className="text-slate-400 text-sm truncate">{word.meaning}</p>
                    </div>
                    <div className="flex gap-1 shrink-0">
                      {!isWrongTab && (
                        <button
                          onClick={() => startEdit(word)}
                          className="p-2 rounded-lg bg-slate-700/30 hover:bg-slate-600/50 text-slate-400 hover:text-sky-300 transition-all"
                        >
                          <Edit2 size={16} />
                        </button>
                      )}
                      <button
                        onClick={() =>
                          isWrongTab ? removeWrongWord(word.id) : deleteWord(word.id)
                        }
                        className={`p-2 rounded-lg bg-slate-700/30 transition-all ${
                          isWrongTab
                            ? "hover:bg-rose-500/30 text-slate-400 hover:text-rose-300"
                            : "hover:bg-rose-500/30 text-slate-400 hover:text-rose-300"
                        }`}
                      >
                        <Trash2 size={16} />
                      </button>
                    </div>
                  </div>
                )}
              </div>
            ))}
          </div>
        </div>

        <div className="flex flex-col gap-2">
          {!isWrongTab ? (
            <>
              <div className="grid grid-cols-3 gap-2">
                <button
                  onClick={() => {
                    setShowAdd(true);
                    setShowImport(false);
                  }}
                  disabled={showAdd}
                  className="py-3 bg-gradient-to-r from-emerald-500 to-teal-500 hover:from-emerald-400 hover:to-teal-400 disabled:opacity-50 disabled:cursor-not-allowed text-white font-bold rounded-xl transition-all shadow-lg shadow-emerald-500/30 flex items-center justify-center gap-1.5 text-sm"
                >
                  <Plus size={16} /> 添加
                </button>
                <button
                  onClick={() => {
                    setShowImport(true);
                    setShowAdd(false);
                  }}
                  disabled={showImport}
                  className="py-3 bg-gradient-to-r from-violet-500 to-purple-500 hover:from-violet-400 hover:to-purple-400 disabled:opacity-50 disabled:cursor-not-allowed text-white font-bold rounded-xl transition-all shadow-lg shadow-violet-500/30 flex items-center justify-center gap-1.5 text-sm"
                >
                  <Upload size={16} /> 导入
                </button>
                <button
                  onClick={handleExport}
                  className="py-3 bg-gradient-to-r from-sky-500 to-cyan-500 hover:from-sky-400 hover:to-cyan-400 text-white font-bold rounded-xl transition-all shadow-lg shadow-sky-500/30 flex items-center justify-center gap-1.5 text-sm"
                >
                  <Download size={16} /> 导出
                </button>
              </div>
            </>
          ) : (
            <button
              onClick={clearWrongWords}
              disabled={wrongWords.length === 0}
              className="w-full py-3 bg-gradient-to-r from-rose-500 to-red-500 hover:from-rose-400 hover:to-red-400 disabled:opacity-50 disabled:cursor-not-allowed text-white font-bold rounded-xl transition-all shadow-lg shadow-rose-500/30 flex items-center justify-center gap-2"
            >
              <Trash2 size={18} /> 清空错题本
            </button>
          )}
          <button
            onClick={onClose}
            className="w-full py-3 bg-slate-700/50 hover:bg-slate-600/50 text-slate-300 rounded-xl transition-all border border-slate-600/50 font-medium"
          >
            关闭
          </button>
        </div>
      </div>
    </div>
  );
}