import { useEffect, useState, useRef } from "react";
import { useSearchParams, useNavigate } from "react-router-dom";
import { RotateCcw, Undo2, HelpCircle, Lightbulb, Home as HomeIcon, Coins, ArrowLeftRight, XCircle, Shuffle, X, Settings, Brain } from "lucide-react";
import { useGameStore } from "@/store/useGameStore";
import { useWordStore } from "@/store/useWordStore";
import { audioManager } from "@/utils/audioManager";
import { getUserInfo } from "@/utils/userInfo";
import GameBoard from "@/components/GameBoard";
import RulesModal from "@/components/RulesModal";
import WinModal from "@/components/WinModal";
import FailModal from "@/components/FailModal";
import ShopModal from "@/components/ShopModal";
import SettingsModal from "@/components/SettingsModal";
import QuizModal from "@/components/QuizModal";

export default function Home() {
  const navigate = useNavigate();
  const initGame = useGameStore((s) => s.initGame);
  const applyItem = useGameStore((s) => s.applyItem);
  const moveHistory = useGameStore((s) => s.moveHistory);
  const isWon = useGameStore((s) => s.isWon);
  const isFailed = useGameStore((s) => s.isFailed);
  const level = useGameStore((s) => s.level);
  const hintCells = useGameStore((s) => s.hintCells);
  const clearHint = useGameStore((s) => s.clearHint);
  const checkDeadlock = useGameStore((s) => s.checkDeadlock);
  const remainingBricks = useGameStore((s) => s.remainingBricks);
  const board = useGameStore((s) => s.board);
  const saveGame = useGameStore((s) => s.saveGame);
  const loadGame = useGameStore((s) => s.loadGame);
  const coins = useGameStore((s) => s.coins);
  const inventory = useGameStore((s) => s.inventory);
  const activeTool = useGameStore((s) => s.activeTool);
  const cancelTool = useGameStore((s) => s.cancelTool);

  const loadWords = useWordStore((s) => s.loadWords);
  const resetLevelSessions = useWordStore((s) => s.resetLevelSessions);
  const quizSessionsLeft = useWordStore((s) => s.quizSessionsLeft);
  const currentWordLevel = useWordStore((s) => s.currentLevel);

  const [searchParams] = useSearchParams();
  const [showRules, setShowRules] = useState(false);
  const [showShop, setShowShop] = useState(false);
  const [showSettings, setShowSettings] = useState(false);
  const [showQuiz, setShowQuiz] = useState(false);
  const initialized = useRef(false);

  useEffect(() => {
    if (initialized.current) return;
    initialized.current = true;

    const fresh = searchParams.get("fresh") === "1";
    if (fresh) {
      initGame(true, true);
    } else {
      const loaded = loadGame();
      if (!loaded) {
        initGame(true);
      }
    }
    loadWords();
  }, [initGame, loadGame, searchParams, loadWords]);

  useEffect(() => {
    if (!initialized.current) return;
    if (level !== currentWordLevel) {
      resetLevelSessions(level);
    }
  }, [level, currentWordLevel, resetLevelSessions]);

  useEffect(() => {
    if (!initialized.current) return;
    if (board.length === 0) return;
    saveGame();
  }, [board, level, remainingBricks, saveGame]);

  useEffect(() => {
    if (!initialized.current) return;
    // 初始化音频管理器，加载所有背景音乐文件
    audioManager.loadAllBgmFiles();
  }, []);

  useEffect(() => {
    if (!initialized.current) return;
    // 初始化用户信息（首次访问时生成 UUID 和默认昵称）
    getUserInfo();
  }, [initialized.current]);

  const deadlockTimerRef = useRef<number | null>(null);
  useEffect(() => {
    if (!isWon && remainingBricks > 0 && board.length > 0) {
      if (deadlockTimerRef.current !== null) {
        clearTimeout(deadlockTimerRef.current);
      }
      deadlockTimerRef.current = window.setTimeout(() => {
        deadlockTimerRef.current = null;
        checkDeadlock();
      }, 800);
    }
    return () => {
      if (deadlockTimerRef.current !== null) {
        clearTimeout(deadlockTimerRef.current);
        deadlockTimerRef.current = null;
      }
    };
  }, [remainingBricks, isWon, board, checkDeadlock]);

  const canUndo = moveHistory.length > 0 && !isWon && !isFailed;

  return (
    <div className="h-screen w-full touch-none overscroll-none relative overflow-hidden">
      <div
        className="absolute inset-0 pointer-events-none"
        style={{
          backgroundImage:
            "url(https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=pixel%20art%20landscape%20green%20grass%20field%20with%20flowers%20distant%20forest%20trees%20blue%20sky%20warm%20sunlight%208bit%20style%20game%20background&image_size=portrait_9_16)",
          backgroundSize: "cover",
          backgroundPosition: "center",
          backgroundRepeat: "no-repeat",
          animation: "windSway 12s ease-in-out infinite",
          transformOrigin: "center center",
        }}
      />
      <div
        className="absolute inset-0 pointer-events-none"
        style={{
          background:
            "linear-gradient(180deg, rgba(0,0,0,0.25) 0%, rgba(0,0,0,0.15) 40%, rgba(0,0,0,0.35) 100%)",
        }}
      />

      <div className="relative z-10 h-full w-full flex flex-col pt-2 pb-2">
        <header className="w-full flex items-center justify-between py-1 px-3 shrink-0">
          <button
            onClick={() => navigate("/")}
            className="w-9 h-9 sm:w-10 sm:h-10 rounded-full bg-slate-800/60 backdrop-blur-sm border border-slate-600/50 flex items-center justify-center text-white hover:scale-110 active:scale-95 transition-transform"
          >
            <HomeIcon size={18} />
          </button>

          <h1 className="text-lg sm:text-xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-amber-200 via-yellow-300 to-orange-300 drop-shadow-lg">
            第 {level} 关
          </h1>

          <div className="flex gap-1.5">
            <button
              onClick={() => setShowQuiz(true)}
              className={`w-9 h-9 sm:w-10 sm:h-10 rounded-full backdrop-blur-sm border flex items-center justify-center hover:scale-110 active:scale-95 transition-transform relative ${
                quizSessionsLeft > 0
                  ? "bg-violet-500/30 border-violet-400/50 text-violet-200"
                  : "bg-slate-800/60 border-slate-600/50 text-slate-500"
              }`}
            >
              <Brain size={16} />
              {quizSessionsLeft > 0 && (
                <span className="absolute -top-0.5 -right-0.5 w-4 h-4 bg-violet-500 rounded-full flex items-center justify-center text-white text-[10px] font-bold border border-violet-300">
                  {quizSessionsLeft}
                </span>
              )}
            </button>
            <button
              onClick={() => setShowSettings(true)}
              className="w-9 h-9 sm:w-10 sm:h-10 rounded-full bg-slate-800/60 backdrop-blur-sm border border-slate-600/50 flex items-center justify-center text-white hover:scale-110 active:scale-95 transition-transform"
            >
              <Settings size={16} />
            </button>
          </div>
        </header>

        <div className="w-full flex-1 flex items-center justify-center min-h-0 px-1 sm:px-2">
          <div className="w-full max-w-md h-full flex items-center justify-center">
            <GameBoard />
          </div>
        </div>

        <div className="w-full flex flex-col items-center gap-1 pt-1 pb-1 px-3 shrink-0">
          <div className="flex items-center">
            <button
              onClick={() => setShowShop(true)}
              className="flex items-center gap-1.5 bg-amber-500/20 hover:bg-amber-500/30 backdrop-blur-sm rounded-full px-3.5 py-1 border border-amber-400/30 transition-all hover:scale-105 active:scale-95"
            >
              <Coins size={14} className="text-amber-400" />
              <span className="text-amber-300 font-bold text-xs">{coins}</span>
            </button>
          </div>

          {activeTool && (
            <div className="w-full flex items-center justify-center gap-2">
              <div className="flex items-center gap-2 bg-purple-500/30 rounded-full px-4 py-1.5 border border-purple-400/50">
                <span className="text-purple-200 text-xs">
                  {activeTool === "swap" ? "请选择两个方块交换位置" : "请选择要消除的方块类型"}
                </span>
              </div>
              <button
                onClick={cancelTool}
                className="w-7 h-7 rounded-full bg-rose-600/80 hover:bg-rose-500/80 flex items-center justify-center text-white transition-all hover:scale-110 active:scale-95"
              >
                <X size={14} />
              </button>
            </div>
          )}

          <div className="flex items-center justify-center gap-1">
            <div className="relative group">
              <button
                onClick={() => {
                  if (hintCells.length > 0) {
                    clearHint();
                  } else {
                    applyItem("hint");
                  }
                }}
                disabled={isWon || isFailed || !!activeTool}
                className="relative w-10 h-10 rounded-xl bg-gradient-to-br from-amber-600/80 to-orange-700/80 hover:from-amber-500/80 hover:to-orange-600/80 border border-amber-400/50 flex items-center justify-center transition-all hover:scale-105 active:scale-95 shadow-lg disabled:opacity-40 disabled:cursor-not-allowed disabled:hover:scale-100"
              >
                <Lightbulb size={16} className="text-amber-100" />
                <div className="absolute -top-1 -right-1 w-4 h-4 bg-red-500 rounded-full flex items-center justify-center text-white text-[10px] font-bold border border-red-300">
                  {inventory.hint}
                </div>
              </button>
            </div>

            <div className="relative group">
              <button
                onClick={() => applyItem("undo")}
                disabled={!canUndo || inventory.undo <= 0 || !!activeTool}
                className="relative w-10 h-10 rounded-xl bg-gradient-to-br from-blue-600/80 to-indigo-700/80 hover:from-blue-500/80 hover:to-indigo-600/80 border border-blue-400/50 flex items-center justify-center transition-all hover:scale-105 active:scale-95 shadow-lg disabled:opacity-40 disabled:cursor-not-allowed disabled:hover:scale-100"
              >
                <Undo2 size={16} className="text-blue-100" />
                <div className="absolute -top-1 -right-1 w-4 h-4 bg-red-500 rounded-full flex items-center justify-center text-white text-[10px] font-bold border border-red-300">
                  {inventory.undo}
                </div>
              </button>
            </div>

            <div className="relative group">
              <button
                onClick={() => applyItem("restart")}
                disabled={isWon || isFailed || inventory.restart <= 0 || !!activeTool}
                className="relative w-10 h-10 rounded-xl bg-gradient-to-br from-rose-600/80 to-red-700/80 hover:from-rose-500/80 hover:to-red-600/80 border border-rose-400/50 flex items-center justify-center transition-all hover:scale-105 active:scale-95 shadow-lg disabled:opacity-40 disabled:cursor-not-allowed disabled:hover:scale-100"
              >
                <RotateCcw size={16} className="text-rose-100" />
                <div className="absolute -top-1 -right-1 w-4 h-4 bg-red-500 rounded-full flex items-center justify-center text-white text-[10px] font-bold border border-red-300">
                  {inventory.restart}
                </div>
              </button>
            </div>

            <div className="relative group">
              <button
                onClick={() => applyItem("swap")}
                disabled={isWon || isFailed || inventory.swap <= 0 || !!activeTool}
                className={`relative w-10 h-10 rounded-xl bg-gradient-to-br from-violet-600/80 to-purple-700/80 hover:from-violet-500/80 hover:to-purple-600/80 border flex items-center justify-center transition-all hover:scale-105 active:scale-95 shadow-lg disabled:opacity-40 disabled:cursor-not-allowed disabled:hover:scale-100 ${activeTool === "swap" ? "border-white ring-2 ring-violet-400 animate-pulse" : "border-violet-400/50"}`}
              >
                <ArrowLeftRight size={16} className="text-violet-100" />
                <div className="absolute -top-1 -right-1 w-4 h-4 bg-red-500 rounded-full flex items-center justify-center text-white text-[10px] font-bold border border-red-300">
                  {inventory.swap}
                </div>
              </button>
            </div>

            <div className="relative group">
              <button
                onClick={() => applyItem("clearType")}
                disabled={isWon || isFailed || inventory.clearType <= 0 || !!activeTool}
                className={`relative w-10 h-10 rounded-xl bg-gradient-to-br from-red-600/80 to-rose-700/80 hover:from-red-500/80 hover:to-rose-600/80 border flex items-center justify-center transition-all hover:scale-105 active:scale-95 shadow-lg disabled:opacity-40 disabled:cursor-not-allowed disabled:hover:scale-100 ${activeTool === "clearType" ? "border-white ring-2 ring-red-400 animate-pulse" : "border-red-400/50"}`}
              >
                <XCircle size={16} className="text-red-100" />
                <div className="absolute -top-1 -right-1 w-4 h-4 bg-red-500 rounded-full flex items-center justify-center text-white text-[10px] font-bold border border-red-300">
                  {inventory.clearType}
                </div>
              </button>
            </div>

            <div className="relative group">
              <button
                onClick={() => applyItem("shuffle")}
                disabled={isWon || isFailed || inventory.shuffle <= 0 || !!activeTool}
                className="relative w-10 h-10 rounded-xl bg-gradient-to-br from-emerald-600/80 to-green-700/80 hover:from-emerald-500/80 hover:to-green-600/80 border border-emerald-400/50 flex items-center justify-center transition-all hover:scale-105 active:scale-95 shadow-lg disabled:opacity-40 disabled:cursor-not-allowed disabled:hover:scale-100"
              >
                <Shuffle size={16} className="text-emerald-100" />
                <div className="absolute -top-1 -right-1 w-4 h-4 bg-red-500 rounded-full flex items-center justify-center text-white text-[10px] font-bold border border-red-300">
                  {inventory.shuffle}
                </div>
              </button>
            </div>

            <div className="relative group">
              <button
                onClick={() => setShowRules(true)}
                className="relative w-10 h-10 rounded-xl bg-gradient-to-br from-cyan-600/80 to-teal-700/80 hover:from-cyan-500/80 hover:to-teal-600/80 border border-cyan-400/50 flex items-center justify-center transition-all hover:scale-105 active:scale-95 shadow-lg"
              >
                <HelpCircle size={16} className="text-cyan-100" />
              </button>
            </div>
          </div>

          {import.meta.env.DEV && (
            <div className="flex items-center justify-center gap-2 mt-1">
              <button
                onClick={() => useGameStore.getState().simulateWin()}
                className="px-2.5 py-0.5 bg-emerald-600/70 hover:bg-emerald-500/70 text-white text-[10px] rounded-full border border-emerald-400/40 transition-all hover:scale-105 active:scale-95"
              >
                模拟通关
              </button>
              <button
                onClick={() => useGameStore.getState().simulateFail()}
                className="px-2.5 py-0.5 bg-red-600/70 hover:bg-red-500/70 text-white text-[10px] rounded-full border border-red-400/40 transition-all hover:scale-105 active:scale-95"
              >
                模拟失败
              </button>
            </div>
          )}
        </div>
      </div>

      <RulesModal open={showRules} onClose={() => setShowRules(false)} />
      <WinModal open={isWon} />
      <FailModal open={isFailed} onUseItem={() => setShowQuiz(true)} onGoHome={() => navigate("/")} />
      <ShopModal open={showShop} onClose={() => setShowShop(false)} />
      <SettingsModal open={showSettings} onClose={() => setShowSettings(false)} />
      <QuizModal open={showQuiz} onClose={() => setShowQuiz(false)} />
    </div>
  );
}