import {
  Board,
  Position,
  ConnectedGroup,
  Direction,
  ROWS,
  COLS,
  BRICK_TYPES,
  BRICKS_PER_TYPE,
  getFrozenCount,
} from "@/types/game";

export function createEmptyBoard(): Board {
  const board: Board = [];
  for (let row = 0; row < ROWS; row++) {
    const rowArr = [];
    for (let col = 0; col < COLS; col++) {
      rowArr.push({ row, col, brick: null, frozen: false });
    }
    board.push(rowArr);
  }
  return board;
}

function shuffle<T>(array: T[]): T[] {
  const arr = [...array];
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr;
}

// 完全随机布局（原行为，高关卡使用）
function initializeRandomBoard(): Board {
  const board = createEmptyBoard();

  const allBricks: number[] = [];
  for (let type = 0; type < BRICK_TYPES; type++) {
    for (let i = 0; i < BRICKS_PER_TYPE; i++) {
      allBricks.push(type);
    }
  }

  const shuffled = shuffle(allBricks);
  let idx = 0;

  for (let row = 0; row < ROWS; row++) {
    for (let col = 0; col < COLS; col++) {
      board[row][col].brick = shuffled[idx];
      board[row][col].frozen = false;
      idx++;
    }
  }

  return board;
}

// 聚集布局：同类型方块优先放在种子点附近，降低难度
function initializeClusteredBoard(clusterRadius: number): Board {
  const board = createEmptyBoard();

  // 收集所有位置
  const allPositions: Position[] = [];
  for (let row = 0; row < ROWS; row++) {
    for (let col = 0; col < COLS; col++) {
      allPositions.push({ row, col });
    }
  }

  // 对每种类型，选种子点 + 聚集放置
  for (let type = 0; type < BRICK_TYPES; type++) {
    // 找当前空位
    const emptyPositions = allPositions.filter(
      (p) => board[p.row][p.col].brick === null
    );
    if (emptyPositions.length === 0) break;

    // 随机选种子点
    const seed =
      emptyPositions[Math.floor(Math.random() * emptyPositions.length)];
    board[seed.row][seed.col].brick = type;

    // 剩余 BRICKS_PER_TYPE - 1 个方块聚集放置
    for (let i = 1; i < BRICKS_PER_TYPE; i++) {
      const candidates = allPositions.filter(
        (p) =>
          board[p.row][p.col].brick === null &&
          Math.abs(p.row - seed.row) + Math.abs(p.col - seed.col) <=
            clusterRadius
      );

      if (candidates.length > 0) {
        const pos =
          candidates[Math.floor(Math.random() * candidates.length)];
        board[pos.row][pos.col].brick = type;
      } else {
        // 范围内无空位，退化为随机放置
        const remaining = allPositions.filter(
          (p) => board[p.row][p.col].brick === null
        );
        if (remaining.length === 0) break;
        const pos =
          remaining[Math.floor(Math.random() * remaining.length)];
        board[pos.row][pos.col].brick = type;
      }
    }
  }

  return board;
}

// 标记冰冻方块：随机选 N 个有方块的位置标记为冰冻
function markFrozenBlocks(board: Board, count: number): void {
  if (count <= 0) return;
  const candidates: Position[] = [];
  for (let r = 0; r < ROWS; r++) {
    for (let c = 0; c < COLS; c++) {
      if (board[r][c].brick !== null) {
        candidates.push({ row: r, col: c });
      }
    }
  }
  for (let i = candidates.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [candidates[i], candidates[j]] = [candidates[j], candidates[i]];
  }
  for (let i = 0; i < Math.min(count, candidates.length); i++) {
    board[candidates[i].row][candidates[i].col].frozen = true;
  }
}

// 基于关卡的布局生成：低关卡聚集（简单），高关卡随机（困难）
export function initializeBoard(level?: number): Board {
  if (level === undefined) {
    return initializeRandomBoard();
  }

  let board: Board;
  if (level >= 8) {
    board = initializeRandomBoard();
  } else {
    const clusterRadius = level + 9;
    board = initializeRandomBoard();
    for (let attempt = 0; attempt < 10; attempt++) {
      const candidate = initializeClusteredBoard(clusterRadius);
      if (findFirstEliminablePair(candidate)) {
        board = candidate;
        break;
      }
    }
  }

  const frozenCount = getFrozenCount(level);
  if (frozenCount > 0) {
    markFrozenBlocks(board, frozenCount);
  }

  return board;
}

export function findConnectedGroup(
  board: Board,
  startRow: number,
  startCol: number
): ConnectedGroup | null {
  const cell = board[startRow]?.[startCol];
  if (!cell || cell.brick === null) return null;

  const type = cell.brick;
  const visited = new Set<string>();
  const positions: Position[] = [];
  const queue: Position[] = [{ row: startRow, col: startCol }];
  const directions = [
    [-1, 0],
    [1, 0],
    [0, -1],
    [0, 1],
  ];

  while (queue.length > 0) {
    const pos = queue.shift()!;
    const key = `${pos.row},${pos.col}`;
    if (visited.has(key)) continue;
    visited.add(key);

    const cell = board[pos.row]?.[pos.col];
    if (!cell || cell.brick !== type) continue;

    positions.push(pos);

    for (const [dr, dc] of directions) {
      const newRow = pos.row + dr;
      const newCol = pos.col + dc;
      const newKey = `${newRow},${newCol}`;
      if (
        newRow >= 0 &&
        newRow < ROWS &&
        newCol >= 0 &&
        newCol < COLS &&
        !visited.has(newKey)
      ) {
        queue.push({ row: newRow, col: newCol });
      }
    }
  }

  return { type, positions };
}

export function findAdjacentSameType(
  board: Board,
  row: number,
  col: number
): Position[] {
  const cell = board[row]?.[col];
  if (!cell || cell.brick === null) return [];
  // 冰冻方块不参与消除
  if (cell.frozen) return [];

  const type = cell.brick;
  const result: Position[] = [];
  const directions = [
    [-1, 0],
    [1, 0],
    [0, -1],
    [0, 1],
  ];

  for (const [dr, dc] of directions) {
    let curRow = row + dr;
    let curCol = col + dc;

    while (
      curRow >= 0 &&
      curRow < ROWS &&
      curCol >= 0 &&
      curCol < COLS
    ) {
      const curCell = board[curRow][curCol];
      if (curCell.brick === null) {
        curRow += dr;
        curCol += dc;
        continue;
      }
      // 冰冻方块可作为消除目标，但仍阻挡视线
      if (curCell.brick === type) {
        result.push({ row: curRow, col: curCol });
      }
      break;
    }
  }

  return result;
}

export function clearPair(board: Board, pos1: Position, pos2: Position): Board {
  const newBoard = board.map((row) => row.map((cell) => ({ ...cell })));
  newBoard[pos1.row][pos1.col].brick = null;
  newBoard[pos2.row][pos2.col].brick = null;
  return newBoard;
}

export function countRemainingBricks(board: Board): number {
  let count = 0;
  for (let row = 0; row < ROWS; row++) {
    for (let col = 0; col < COLS; col++) {
      if (board[row][col].brick !== null) count++;
    }
  }
  return count;
}

export function deepCloneBoard(board: Board): Board {
  return board.map((row) => row.map((cell) => ({ ...cell })));
}

// 解冻：检查被消除位置相邻的冰冻方块，返回需解冻的位置
export function unfreezeAdjacent(
  board: Board,
  clearedPositions: Position[]
): Position[] {
  const toUnfreeze: Position[] = [];
  const clearedSet = new Set(clearedPositions.map((p) => `${p.row},${p.col}`));
  const checked = new Set<string>();

  for (const pos of clearedPositions) {
    const directions = [
      [-1, 0],
      [1, 0],
      [0, -1],
      [0, 1],
    ];
    for (const [dr, dc] of directions) {
      const r = pos.row + dr;
      const c = pos.col + dc;
      const key = `${r},${c}`;
      if (checked.has(key)) continue;
      checked.add(key);
      if (r < 0 || r >= ROWS || c < 0 || c >= COLS) continue;
      const cell = board[r][c];
      if (cell.brick !== null && cell.frozen && !clearedSet.has(key)) {
        toUnfreeze.push({ row: r, col: c });
      }
    }
  }

  return toUnfreeze;
}

const DIR_DELTA: Record<Direction, [number, number]> = {
  up: [-1, 0],
  down: [1, 0],
  left: [0, -1],
  right: [0, 1],
};

export function findPushChain(
  board: Board,
  startRow: number,
  startCol: number,
  direction: Direction
): Position[] {
  const cell = board[startRow]?.[startCol];
  if (!cell || cell.brick === null) return [];
  // 冰冻方块不能被推动
  if (cell.frozen) return [];

  const [dr, dc] = DIR_DELTA[direction];
  const chain: Position[] = [{ row: startRow, col: startCol }];
  const visited = new Set<string>([`${startRow},${startCol}`]);

  let curRow = startRow + dr;
  let curCol = startCol + dc;
  while (
    curRow >= 0 &&
    curRow < ROWS &&
    curCol >= 0 &&
    curCol < COLS &&
    board[curRow][curCol].brick !== null &&
    !board[curRow][curCol].frozen // 冰冻方块阻挡推动
  ) {
    const key = `${curRow},${curCol}`;
    if (visited.has(key)) break;
    visited.add(key);
    chain.push({ row: curRow, col: curCol });
    curRow += dr;
    curCol += dc;
  }

  return chain;
}

export function canPushChain(
  board: Board,
  chain: Position[],
  direction: Direction
): boolean {
  if (chain.length === 0) return false;

  const [dr, dc] = DIR_DELTA[direction];
  const chainKeys = new Set(chain.map((p) => `${p.row},${p.col}`));

  for (const pos of chain) {
    const newRow = pos.row + dr;
    const newCol = pos.col + dc;

    if (newRow < 0 || newRow >= ROWS || newCol < 0 || newCol >= COLS) {
      return false;
    }

    const targetCell = board[newRow][newCol];
    const targetKey = `${newRow},${newCol}`;

    if (targetCell.brick !== null && !chainKeys.has(targetKey)) {
      return false;
    }
  }

  return true;
}

export function pushChain(
  board: Board,
  chain: Position[],
  direction: Direction
): Board {
  if (chain.length === 0) return board;

  const [dr, dc] = DIR_DELTA[direction];
  const newBoard = deepCloneBoard(board);

  const bricks: (number | null)[] = chain.map(
    (p) => board[p.row][p.col].brick
  );

  for (const pos of chain) {
    newBoard[pos.row][pos.col].brick = null;
  }

  for (let i = 0; i < chain.length; i++) {
    const newRow = chain[i].row + dr;
    const newCol = chain[i].col + dc;
    newBoard[newRow][newCol].brick = bricks[i];
  }

  return newBoard;
}

export function maxPhysicalPushSteps(
  board: Board,
  startRow: number,
  startCol: number,
  direction: Direction
): number {
  const initialChain = findPushChain(board, startRow, startCol, direction);
  if (initialChain.length === 0) return 0;

  const [dr, dc] = DIR_DELTA[direction];
  let steps = 0;
  let currentBoard = board;
  let chain = initialChain;

  while (true) {
    if (!canPushChain(currentBoard, chain, direction)) break;
    currentBoard = pushChain(currentBoard, chain, direction);
    chain = chain.map((p) => ({ row: p.row + dr, col: p.col + dc }));
    steps++;
  }

  return steps;
}

export function findCellAdjacentPairs(
  board: Board,
  pos: Position
): Array<[Position, Position]> {
  const pairs: Array<[Position, Position]> = [];
  const type = board[pos.row]?.[pos.col]?.brick;
  if (type === null || type === undefined) return pairs;

  const adjacents = findAdjacentSameType(board, pos.row, pos.col);
  for (const adj of adjacents) {
    pairs.push([pos, adj]);
  }

  return pairs;
}

export function findFirstEliminablePair(
  board: Board
): [Position, Position] | null {
  const directions: Direction[] = ["up", "down", "left", "right"];

  // 单一工作棋盘，避免反复深拷贝
  const workBoard = deepCloneBoard(board);

  for (let r = 0; r < ROWS; r++) {
    for (let c = 0; c < COLS; c++) {
      if (board[r][c].brick === null) continue;
      // 冰冻方块不能作为消除起点
      if (board[r][c].frozen) continue;

      // 检查直接相邻（无需推动）
      const currentAdjacents = findAdjacentSameType(board, r, c);
      if (currentAdjacents.length > 0) {
        return [{ row: r, col: c }, currentAdjacents[0]];
      }

      for (const dir of directions) {
        // 重置工作棋盘到原始状态
        for (let rr = 0; rr < ROWS; rr++) {
          for (let cc = 0; cc < COLS; cc++) {
            workBoard[rr][cc].brick = board[rr][cc].brick;
          }
        }

        const initialChain = findPushChain(workBoard, r, c, dir);
        if (initialChain.length === 0) continue;

        const [dr, dc] = DIR_DELTA[dir];
        let chain = initialChain;

        while (canPushChain(workBoard, chain, dir)) {
          // 原地推动，避免深拷贝
          const bricks = chain.map((p) => workBoard[p.row][p.col].brick);
          for (const pos of chain) {
            workBoard[pos.row][pos.col].brick = null;
          }
          for (let i = 0; i < chain.length; i++) {
            workBoard[chain[i].row + dr][chain[i].col + dc].brick = bricks[i];
          }
          chain = chain.map((p) => ({ row: p.row + dr, col: p.col + dc }));

          // 只检查起点方块（chain[0]）新位置的配对，与 finalizeDragMove 行为一致
          const startPos = chain[0];
          const adjacents = findAdjacentSameType(workBoard, startPos.row, startPos.col);
          if (adjacents.length > 0) {
            return [{ row: r, col: c }, adjacents[0]];
          }
        }
      }
    }
  }

  return null;
}

